# ! [doc = " TLS, but async-signal-safe."] # ! [doc = ""] # ! [doc = " Unfortunately, because thread local storage isn't async-signal-safe, we"] # ! [doc = " cannot soundly use it in our stack overflow handler. While this works"] # ! [doc = " without problems on most platforms, it can lead to undefined behaviour"] # ! [doc = " on others (such as GNU/Linux). Luckily, the POSIX specification documents"] # ! [doc = " two thread-specific values that can be accessed in asynchronous signal"] # ! [doc = " handlers: the value of `pthread_self()` and the address of `errno`. As"] # ! [doc = " `pthread_t` is an opaque platform-specific type, we use the address of"] # ! [doc = " `errno` here. As it is thread-specific and does not change over the"] # ! [doc = " lifetime of a thread, we can use `&errno` as a key for a `BTreeMap`"] # ! [doc = " that stores thread-specific data."] # ! [doc = ""] # ! [doc = " Concurrent access to this map is synchronized by two locks – an outer"] # ! [doc = " [`Mutex`] and an inner spin lock that also remembers the identity of"] # ! [doc = " the lock owner:"] # ! [doc = " * The spin lock is the primary means of synchronization: since it only"] # ! [doc = "   uses native atomics, it can be soundly used inside the signal handle"] # ! [doc = "   as opposed to [`Mutex`], which might not be async-signal-safe."] # ! [doc = " * The [`Mutex`] prevents busy-waiting in the setup logic, as all accesses"] # ! [doc = "   there are performed with the [`Mutex`] held, which makes the spin-lock"] # ! [doc = "   redundant in the common case."] # ! [doc = " * Finally, by using the `errno` address as the locked value of the spin"] # ! [doc = "   lock, we can detect cases where a SIGSEGV occurred while the thread"] # ! [doc = "   info is being modified."] use split_decls_genesis :: ourprelude :: * ; use crate :: collections :: BTreeMap ; use crate :: hint :: spin_loop ; use crate :: ops :: Range ; use crate :: sync :: Mutex ; use crate :: sync :: atomic :: { AtomicUsize , Ordering } ; use crate :: sys :: os :: errno_location ; pub struct ThreadInfo { pub guard_page_range : Range < usize > , pub thread_name : Option < Box < str > > , } static LOCK : Mutex < () > = Mutex :: new (()) ; static SPIN_LOCK : AtomicUsize = AtomicUsize :: new (0) ; static mut THREAD_INFO : BTreeMap < usize , ThreadInfo > = BTreeMap :: new () ; struct UnlockOnDrop ; impl Drop for UnlockOnDrop { fn drop (& mut self) { SPIN_LOCK . store (0 , Ordering :: Release) ; } } #[doc = " Get the current thread's information, if available."] #[doc = ""] #[doc = " Calling this function might freeze other threads if they attempt to modify"] #[doc = " their thread information. Thus, the caller should ensure that the process"] #[doc = " is aborted shortly after this function is called."] #[doc = ""] #[doc = " This function is guaranteed to be async-signal-safe if `f` is too."] pub fn with_current_info < R > (f : impl FnOnce (Option < & ThreadInfo >) -> R) -> R { let this = errno_location () . addr () ; let mut attempt = 0 ; let _guard = loop { if attempt == 10_000_000 { rtprintpanic ! ("deadlock in SIGSEGV handler") ; return f (None) ; } match SPIN_LOCK . compare_exchange (0 , this , Ordering :: Acquire , Ordering :: Relaxed) { Ok (_) => break UnlockOnDrop , Err (owner) if owner == this => { rtabort ! ("a thread received SIGSEGV while modifying its stack overflow information") } Err (_) => { spin_loop () ; attempt += 1 ; } } } ; let thread_info = unsafe { & * (& raw const THREAD_INFO) } ; f (thread_info . get (& this)) } fn spin_lock_in_setup (this : usize) -> UnlockOnDrop { loop { match SPIN_LOCK . compare_exchange (0 , this , Ordering :: Acquire , Ordering :: Relaxed) { Ok (_) => return UnlockOnDrop , Err (owner) if owner == this => { unreachable ! ("the thread info setup logic isn't recursive") } Err (_) => drop (unsafe { libc :: pause () }) , } } } pub fn set_current_info (guard_page_range : Range < usize > , thread_name : Option < Box < str > >) { let this = errno_location () . addr () ; let _lock_guard = LOCK . lock () ; let _spin_guard = spin_lock_in_setup (this) ; let thread_info = unsafe { & mut * (& raw mut THREAD_INFO) } ; thread_info . insert (this , ThreadInfo { guard_page_range , thread_name }) ; } pub fn delete_current_info () { let this = errno_location () . addr () ; let _lock_guard = LOCK . lock () ; let _spin_guard = spin_lock_in_setup (this) ; let thread_info = unsafe { & mut * (& raw mut THREAD_INFO) } ; thread_info . remove (& this) ; }